INSERT INTO `informasi` (`informasi_id`, `nama`, `slug_informasi`, `isi_informasi`, `gambar`, `tgl_informasi`, `hits`, `type`, `id`, `fileunduh`, `sts_aktif`) VALUES
(12, 'Pendaftaran Santri Baru PP Darul Ulum Tlasih Tahun Pelajaran 2026–2027 Resmi Dibuka!', 'pendaftaran-santri-baru-pp-darul-ulum-tlasih-tahun-pelajaran-20262027-resmi-dibuka', ' <p data-start=\"199\" data-end=\"420\">Assalamu’alaikum warahmatullahi wabarakatuh.<br data-start=\"243\" data-end=\"246\">\r\nDiberitahukan kepada seluruh masyarakat bahwa <strong data-start=\"292\" data-end=\"337\">Pondok Pesantren Darul Ulum (PPDU) Tlasih</strong> telah <strong data-start=\"344\" data-end=\"417\">resmi membuka Pendaftaran Santri Baru (PSB) Tahun Pelajaran 2026–2027</strong>.</p><p data-start=\"199\" data-end=\"420\">Jenjang yang dibuka:</p><ul data-start=\"448\" data-end=\"536\">\r\n<li data-start=\"448\" data-end=\"477\">\r\n<p data-start=\"450\" data-end=\"477\"><strong data-start=\"450\" data-end=\"475\">TPQ Darul Ulum Tlasih</strong></p>\r\n</li>\r\n<li data-start=\"478\" data-end=\"507\">\r\n<p data-start=\"480\" data-end=\"507\"><strong data-start=\"480\" data-end=\"505\">MTs Darul Ulum Tlasih</strong></p>\r\n</li>\r\n<li data-start=\"508\" data-end=\"536\">\r\n<p data-start=\"510\" data-end=\"536\"><strong data-start=\"510\" data-end=\"534\">MA Darul Ulum Tlasih</strong></p>\r\n</li>\r\n</ul><p data-start=\"538\" data-end=\"737\"><strong data-start=\"541\" data-end=\"570\">Pendaftaran dibuka mulai:</strong> November 2025<br data-start=\"584\" data-end=\"587\"><strong data-start=\"590\" data-end=\"601\">Tempat:</strong> Kantor Sekretariat PSB PPDU Tlasih<br data-start=\"636\" data-end=\"639\"><strong data-start=\"642\" data-end=\"677\">Informasi &amp; pendaftaran online:</strong> https://psbpendarul.ponpes-darululumtlasih.com/login<br data-start=\"693\" data-end=\"696\"><strong data-start=\"699\" data-end=\"720\">Kontak informasi:</strong> 0859-3150-2683</p><p data-start=\"739\" data-end=\"955\">Mari bergabung bersama kami untuk menimba ilmu agama dan umum secara seimbang dalam suasana pesantren yang <strong data-start=\"846\" data-end=\"886\">berakhlak, berilmu, dan berprestasi.</strong><br data-start=\"886\" data-end=\"889\">\r\n✨ <em data-start=\"891\" data-end=\"953\">Belajar, Berjuang, dan Berkhidmat bersama Darul Ulum Tlasih!</em></p><p>\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"957\" data-end=\"1004\">Wassalamu’alaikum warahmatullahi wabarakatuh.</p>', '1762641638_85f78e7f1a8d648d4523.jpg', '2025-11-09', 0, 1, 17, NULL, NULL),
(14, 'Selamat Datang di Pondok Pesantren Darul Ulum Tlasih', 'selamat-datang-di-pondok-pesantren-darul-ulum-tlasih', '  <p style=\"text-align: justify;\"><b>Assalamu’alaikum warahmatullahi wabarakatuh</b>.</p><p style=\"text-align: justify;\">Segala puji dan syukur kita panjatkan ke hadirat Allah Subhanahu wa Ta’ala yang telah melimpahkan rahmat, taufik, serta hidayah-Nya kepada kita semua.</p><p style=\"text-align: justify;\">Shalawat serta salam semoga senantiasa tercurah kepada junjungan kita Nabi Muhammad Shallallahu ‘Alaihi Wasallam, keluarga, sahabat, dan para pengikutnya hingga akhir zaman.</p><p style=\"text-align: justify;\">Dengan penuh rasa syukur, kami ucapkan selamat datang di website resmi Pondok Pesantren Darul Ulum Tlasih.</p><p style=\"text-align: justify;\">Website ini kami hadirkan sebagai pusat informasi dan komunikasi resmi antara pesantren dengan masyarakat luas — termasuk santri, wali santri, alumni, dan para pemerhati pendidikan Islam.</p><p style=\"text-align: justify;\">Melalui situs ini, kami berupaya memberikan gambaran menyeluruh tentang kegiatan, program, serta visi-misi Pondok Pesantren Darul Ulum Tlasih dalam mencetak generasi yang berilmu, beramal, dan berakhlakul karimah.</p><p style=\"text-align: justify;\">Pondok Pesantren Darul Ulum Tlasih berdiri dengan tekad yang kuat untuk menjadi lembaga pendidikan Islam yang mampu melahirkan kader umat berdaya guna, berwawasan luas, serta berjiwa sosial tinggi.</p><p style=\"text-align: justify;\">Kami menyelenggarakan pendidikan yang memadukan antara pendalaman ilmu agama (tafaqquh fiddin) dengan penguasaan ilmu pengetahuan dan teknologi modern, agar para santri mampu beradaptasi dengan perkembangan zaman tanpa kehilangan jati diri keislaman.</p><p style=\"text-align: justify;\">Proses pendidikan di pesantren ini dilaksanakan dengan menekankan nilai-nilai keikhlasan, kedisiplinan, tanggung jawab, kesederhanaan, dan kemandirian.</p><p style=\"text-align: justify;\">Setiap santri dibimbing untuk mengamalkan ilmu secara nyata, berperilaku sopan, serta menjadikan akhlakul karimah sebagai pondasi dalam kehidupan sehari-hari.</p><p style=\"text-align: justify;\">Selain itu, kegiatan ekstrakurikuler, organisasi santri, dan pelatihan keterampilan turut menjadi bagian dari pembentukan karakter dan kecakapan hidup.</p><p style=\"text-align: justify;\">Melalui layanan digital ini, pengunjung dapat mengakses berbagai informasi penting seperti profil pesantren, program pendidikan, kegiatan santri, pendaftaran santri baru (PPDB), serta pengumuman resmi yang diperbarui secara berkala.</p><p style=\"text-align: justify;\">Kami berharap website ini dapat menjadi jendela komunikasi yang efektif antara pesantren dengan masyarakat, serta wadah silaturahmi yang mempererat hubungan ukhuwah Islamiyah antar seluruh pihak yang terlibat dalam lingkungan Darul Ulum Tlasih.</p><p style=\"text-align: justify;\">Kami juga menyadari bahwa tantangan dunia pendidikan semakin kompleks. Oleh karena itu, Pondok Pesantren Darul Ulum Tlasih senantiasa berkomitmen untuk terus berinovasi dan berbenah, baik dalam sistem pembelajaran, sarana prasarana, maupun kualitas tenaga pendidik dan pengasuh.</p><p style=\"text-align: justify;\">Kami berupaya menjaga keseimbangan antara nilai-nilai tradisi pesantren yang luhur dan semangat modernisasi pendidikan yang konstruktif.</p><p style=\"text-align: justify;\">Kami percaya bahwa keberhasilan sebuah pesantren tidak hanya diukur dari banyaknya santri atau besarnya bangunan, melainkan dari sejauh mana lembaga ini mampu memberikan manfaat nyata bagi umat dan bangsa.</p><p style=\"text-align: justify;\">Oleh sebab itu, kami mengajak seluruh pihak — wali santri, alumni, masyarakat, dan pemerintah — untuk bersama-sama mendukung dan mendoakan keberlangsungan perjuangan pendidikan di Pondok Pesantren Darul Ulum Tlasih.</p><p style=\"text-align: justify;\">Akhir kata, semoga segala ikhtiar yang dilakukan dalam dunia pendidikan ini menjadi amal jariyah dan memperoleh keberkahan dari Allah Subhanahu wa Ta’ala.</p><p style=\"text-align: justify;\">Terima kasih atas kunjungan Anda di website resmi kami.</p><p style=\"text-align: justify;\"><b>Wassalamu’alaikum warahmatullahi wabarakatuh.</b></p><p style=\"text-align: center;\"><b>— Pimpinan dan Pengasuh Pondok Pesantren Darul Ulum Tlasih</b></p>', '1763008863_0d0f945a0a7139b62596.jpg', '2025-11-13', 17, 0, 1, NULL, NULL),
(15, 'Pondok Pesantren Darul Ulum Tlasih berkomitmen untuk mengintegrasikan pendidikan agama dan umum, dengan tujuan membentuk generasi yang cerdas dalam ilmu pengetahuan dan memiliki akhlak yang baik.', 'pondok-pesantren-darul-ulum-tlasih-berkomitmen-untuk-mengintegrasikan-pendidikan-agama-dan-umum-dengan-tujuan-membentuk-generasi-yang-cerdas-dalam-ilmu-pengetahuan-dan-memiliki-akhlak-yang-baik', ' <p><br></p>', '1763802251_b2ccfde6138a8b984e1b.png', '2025-11-22', 0, 1, 1, NULL, NULL),
(16, 'Tidak semua yang kita inginkan akan kita dapatkan, tapi yakinlah, apa yang diberikan Allah adalah yang terbaik untuk kita.', 'tidak-semua-yang-kita-inginkan-akan-kita-dapatkan-tapi-yakinlah-apa-yang-diberikan-allah-adalah-yang-terbaik-untuk-kita', '<p>.</p>', 'default.png', '2025-11-22', 0, 1, 1, NULL, NULL);
