INSERT INTO `survey_responden` (`responden_id`, `survey_id`, `nohp`, `nama`, `saran`, `tanggal`) VALUES
(16, 1, '0895631373095', 'rega', 'Secara umum kami sangat mengapresiasi pelayanan dan pembinaan yang diberikan. Namun kami berharap ke depan informasi terkait kegiatan, peraturan, dan jadwal dapat disampaikan lebih teratur dan tepat waktu agar wali santri dapat mengikuti perkembangan dengan lebih mudah. Semoga pesantren semakin berkembang dan memberikan manfaat yang lebih luas.', '2025-12-01'),
(17, 5, '0895631373095', 'paero', '', '2025-12-05');
