INSERT INTO `tbl_setaplikasi` (`id_setaplikasi`, `nama`, `alamat`, `no_telp`, `kecamatan`, `kabupaten`, `provinsi`, `website`, `email`, `deskripsi`, `logo`, `sts_sambutan`, `icon`, `google_map`, `nama_pimpinan`, `jabatan_pimpinan`, `sambutan`, `gbr_sambutan`, `link_gmap`, `sosmed_fb`, `sosmed_instagram`, `sosmed_twiter`, `sosmed_youtube`, `kategori_id`, `judul_section`, `sts_section`, `sts_modal`, `ck`, `sts_count`, `sts_rt`, `hplogo`, `wllogo`, `hpbanner`, `wlbanner`, `sts_regis`, `sts_web`, `sts_posting`, `verbost`, `smtp_host`, `smtp_username`, `smtp_password`, `smtp_port`, `smtp_pengirim`, `smtp_pesanbalas`, `g_sitekey`, `g_secretkey`, `vercms`, `verdb`, `konek_opd`, `id_grup`, `footer_cms`, `ukuran_upload`, `tokenwa`, `no_waysender`, `wa_penerima`, `katamutiara`, `namasingkat`, `urlserver`) VALUES
(1, 'YAYASAN PONDOK PESANTREN DARUL ULUM TLASIH', 'Jl. Raya Tlasih, RT.005/RW.001, Tlasih Dua, Tlasih, Kec. Tulangan, Kabupaten Sidoarjo, Jawa Timur 61273', '+6285900255125', 'Lebatukan', 'Sidoarjo', 'Jawa Timur', 'https://ponpes-darululumtlasih.com/', 'ppdarululumtlasih@gmail.com', 'Mencetak Generasi yang Beriman, Berilmu, dan Berakhlak Mulia untuk Membawa Perubahan Positif di Dunia dan Akhirat, melalui Pendidikan yang Menggabungkan Ilmu Pengetahuan dan Nilai Agama, serta Membentuk Karakter Pemimpin yang Bertanggung Jawab dan Peduli terhadap Masyarakat.', '1764934258_623d6c14e921780fed1a.png', '1', 'LOGO PPDU.png', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3080.2617361750777!2d112.61867097367858!3d-7.473929092537809!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2dd7e1d512e0e7f3%3A0x9fd7f1b1a3864702!2sPondok%20Pesantren%20Darul%20Ulum%20Tlasih%20Tulangan!5e1!3m2!1sid!2sid!4v1762421703041!5m2!1sid!2sid\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>', 'Aisatul Mufarrohah, S.Pd.I', 'Ketua Yayasan', '                  <div class=\"m-auto text-base py-[18px] px-3 md:px-4 w-full md:px-5 lg:px-4 xl:px-5\">\r\n<div class=\"mx-auto flex flex-1 gap-4 text-base md:gap-5 lg:gap-6 md:max-w-3xl lg:max-w-[40rem] xl:max-w-[48rem]\">\r\n<div class=\"flex-shrink-0 flex flex-col relative items-end\">\r\n<p data-start=\"192\" data-end=\"240\" style=\"text-align: justify; \"><strong data-start=\"192\" data-end=\"240\">Assalamu’alaikum warahmatullahi wabarakatuh,</strong></p><p data-start=\"242\" data-end=\"638\" style=\"text-align: justify;\">Segala puji bagi Allah SWT, Tuhan semesta alam. Atas limpahan rahmat, taufik, dan hidayah-Nya, kita diberikan kesempatan untuk terus berjuang dalam pendidikan, dakwah, dan pembinaan generasi penerus umat. Shalawat serta salam semoga senantiasa tercurah kepada Nabi Muhammad SAW, teladan terbaik bagi seluruh umat manusia, beserta keluarga, sahabat, dan seluruh pengikut beliau hingga akhir zaman.</p><p data-start=\"640\" data-end=\"1077\" style=\"text-align: justify;\">Dengan penuh rasa syukur, kami menyambut kehadiran Anda di <strong data-start=\"699\" data-end=\"737\">Pondok Pesantren Darul Ulum Tlasih</strong>. Pesantren ini hadir sebagai lembaga pendidikan Islam yang berkomitmen untuk mencetak generasi berilmu, berakhlak, dan siap mengabdi kepada agama, masyarakat, bangsa, dan negara. Kehadirannya dilandasi oleh nilai keikhlasan, perjuangan, serta tekad untuk menjadi bagian dari sistem pendidikan Islam yang modern, relevan, dan berkelanjutan.</p><hr data-start=\"1079\" data-end=\"1082\" style=\"text-align: justify;\"><h3 data-start=\"1084\" data-end=\"1151\" style=\"text-align: justify;\"><strong data-start=\"1088\" data-end=\"1151\">Pesantren Sebagai Pusat Pendidikan dan Pembentukan Karakter</strong></h3><p data-start=\"1153\" data-end=\"1380\" style=\"text-align: justify;\">Pondok Pesantren Darul Ulum Tlasih tidak hanya menjadi tempat santri belajar ilmu agama dan umum, tetapi juga tempat pembentukan karakter, akhlak, dan mental spiritual. Sistem pendidikan yang diterapkan adalah perpaduan antara:</p><ul data-start=\"1382\" data-end=\"1599\">\r\n<li data-start=\"1382\" data-end=\"1484\">\r\n<p data-start=\"1384\" data-end=\"1484\" style=\"text-align: justify;\"><strong data-start=\"1384\" data-end=\"1409\">Metode salaf (klasik)</strong> dengan nilai kedisiplinan, ketawadhuan, dan keberkahan tradisi pesantren</p>\r\n</li>\r\n<li data-start=\"1485\" data-end=\"1599\">\r\n<p data-start=\"1487\" data-end=\"1599\" style=\"text-align: justify;\"><strong data-start=\"1487\" data-end=\"1513\">Metode khalaf (modern)</strong> yang adaptif terhadap perkembangan ilmu pengetahuan, teknologi, dan kebutuhan zaman</p>\r\n</li>\r\n</ul><p data-start=\"1601\" data-end=\"1678\" style=\"text-align: justify;\">Melalui pembinaan tersebut, santri dididik untuk tumbuh menjadi pribadi yang:</p><ul data-start=\"1680\" data-end=\"1889\">\r\n<li data-start=\"1680\" data-end=\"1711\">\r\n<p data-start=\"1682\" data-end=\"1711\" style=\"text-align: justify;\"><strong data-start=\"1682\" data-end=\"1711\">Cerdas secara intelektual</strong></p>\r\n</li>\r\n<li data-start=\"1712\" data-end=\"1751\">\r\n<p data-start=\"1714\" data-end=\"1751\" style=\"text-align: justify;\"><strong data-start=\"1714\" data-end=\"1751\">Kokoh secara aqidah dan spiritual</strong></p>\r\n</li>\r\n<li data-start=\"1752\" data-end=\"1773\">\r\n<p data-start=\"1754\" data-end=\"1773\" style=\"text-align: justify;\"><strong data-start=\"1754\" data-end=\"1773\">Berakhlak mulia</strong></p>\r\n</li>\r\n<li data-start=\"1774\" data-end=\"1820\">\r\n<p data-start=\"1776\" data-end=\"1820\" style=\"text-align: justify;\"><strong data-start=\"1776\" data-end=\"1820\">Mandiri, disiplin, dan bertanggung jawab</strong></p>\r\n</li>\r\n<li data-start=\"1821\" data-end=\"1889\">\r\n<p data-start=\"1823\" data-end=\"1889\" style=\"text-align: justify;\"><strong data-start=\"1823\" data-end=\"1889\">Mampu berperan aktif dalam kehidupan sosial dan kemasyarakatan</strong></p>\r\n</li>\r\n</ul><p data-start=\"1891\" data-end=\"2052\" style=\"text-align: justify;\">Kami yakin, lulusan pesantren ini akan menjadi generasi muslim yang siap berkontribusi secara nyata di berbagai bidang, tanpa meninggalkan nilai-nilai keislaman.</p><hr data-start=\"2054\" data-end=\"2057\" style=\"text-align: justify;\"><h3 data-start=\"2059\" data-end=\"2125\" style=\"text-align: justify;\"><strong data-start=\"2063\" data-end=\"2125\">Website Resmi: Informasi, Transparansi, dan Dakwah Digital</strong></h3><p data-start=\"2127\" data-end=\"2302\" style=\"text-align: justify;\">Sebagai bagian dari modernisasi dan keterbukaan layanan pesantren, kami menghadirkan <strong data-start=\"2212\" data-end=\"2264\">Website Resmi Pondok Pesantren Darul Ulum Tlasih</strong>. Website ini memiliki fungsi sebagai:</p><ul data-start=\"2304\" data-end=\"2537\">\r\n<li data-start=\"2304\" data-end=\"2379\">\r\n<p data-start=\"2306\" data-end=\"2379\" style=\"text-align: justify;\"><strong data-start=\"2306\" data-end=\"2379\">Sumber informasi resmi bagi wali santri, masyarakat, dan calon santri</strong></p>\r\n</li>\r\n<li data-start=\"2380\" data-end=\"2440\">\r\n<p data-start=\"2382\" data-end=\"2440\" style=\"text-align: justify;\"><strong data-start=\"2382\" data-end=\"2440\">Media publikasi kegiatan pesantren dan prestasi santri</strong></p>\r\n</li>\r\n<li data-start=\"2441\" data-end=\"2487\">\r\n<p data-start=\"2443\" data-end=\"2487\" style=\"text-align: justify;\"><strong data-start=\"2443\" data-end=\"2487\">Dokumentasi digital perkembangan lembaga</strong></p>\r\n</li>\r\n<li data-start=\"2488\" data-end=\"2537\">\r\n<p data-start=\"2490\" data-end=\"2537\" style=\"text-align: justify;\"><strong data-start=\"2490\" data-end=\"2537\">Wadah dakwah yang dapat diakses secara luas</strong></p>\r\n</li>\r\n</ul><p data-start=\"2539\" data-end=\"2725\" style=\"text-align: justify;\">Melalui website ini, masyarakat dapat mengetahui profil pesantren, program pendidikan, agenda kegiatan, galeri dokumentasi, hingga informasi penting lainnya secara akurat dan terpercaya.</p><hr data-start=\"2727\" data-end=\"2730\" style=\"text-align: justify;\"><h3 data-start=\"2732\" data-end=\"2797\" style=\"text-align: justify;\"><strong data-start=\"2736\" data-end=\"2797\">PSB Online: Pendaftaran Modern, Efisien, dan Terintegrasi</strong></h3><p data-start=\"2799\" data-end=\"2981\" style=\"text-align: justify;\">Untuk memberikan pelayanan terbaik kepada calon santri dan wali santri, kami menyediakan sistem <strong data-start=\"2895\" data-end=\"2934\">PSB Online (Penerimaan Santri Baru)</strong> yang dapat diakses secara fleksibel dan mudah.</p><p data-start=\"2983\" data-end=\"3031\" style=\"text-align: justify;\">Melalui layanan ini, masyarakat dapat melakukan:</p><ul data-start=\"3033\" data-end=\"3155\">\r\n<li data-start=\"3033\" data-end=\"3067\">\r\n<p data-start=\"3035\" data-end=\"3067\" style=\"text-align: justify;\">Pengisian formulir pendaftaran</p>\r\n</li>\r\n<li data-start=\"3068\" data-end=\"3105\">\r\n<p data-start=\"3070\" data-end=\"3105\" style=\"text-align: justify;\">Unggah dokumen dan berkas digital</p>\r\n</li>\r\n<li data-start=\"3106\" data-end=\"3155\">\r\n<p data-start=\"3108\" data-end=\"3155\" style=\"text-align: justify;\">Informasi seleksi dan verifikasi administrasi</p>\r\n</li>\r\n</ul><p data-start=\"3157\" data-end=\"3261\" style=\"text-align: justify;\">Semua dilakukan melalui sistem yang lebih cepat, efisien, dan transparan tanpa batasan waktu dan lokasi.</p><hr data-start=\"3263\" data-end=\"3266\" style=\"text-align: justify;\"><h3 data-start=\"3268\" data-end=\"3311\" style=\"text-align: justify;\"><strong data-start=\"3272\" data-end=\"3311\">Kolaborasi dan Dukungan Semua Pihak</strong></h3><p data-start=\"3313\" data-end=\"3488\" style=\"text-align: justify;\">Perkembangan pesantren hingga hari ini tidak terlepas dari doa, dukungan, dan partisipasi banyak pihak. Oleh karena itu, kami menyampaikan penghargaan dan terima kasih kepada:</p><ul data-start=\"3490\" data-end=\"3666\">\r\n<li data-start=\"3490\" data-end=\"3533\">\r\n<p data-start=\"3492\" data-end=\"3533\" style=\"text-align: justify;\">Para masyayikh, kiai, dan dewan asatidz</p>\r\n</li>\r\n<li data-start=\"3534\" data-end=\"3564\">\r\n<p data-start=\"3536\" data-end=\"3564\" style=\"text-align: justify;\">Wali santri dan masyarakat</p>\r\n</li>\r\n<li data-start=\"3565\" data-end=\"3617\">\r\n<p data-start=\"3567\" data-end=\"3617\" style=\"text-align: justify;\">Alumni yang terus mendukung pergerakan pesantren</p>\r\n</li>\r\n<li data-start=\"3618\" data-end=\"3666\">\r\n<p data-start=\"3620\" data-end=\"3666\" style=\"text-align: justify;\">Mitra kerja dan lembaga pendukung pendidikan</p>\r\n</li>\r\n</ul><p data-start=\"3668\" data-end=\"3799\" style=\"text-align: justify;\">Kami berharap kolaborasi ini terus terjalin, sehingga pesantren dapat berkembang lebih baik dan memberikan manfaat yang lebih luas.</p><hr data-start=\"3801\" data-end=\"3804\" style=\"text-align: justify;\"><h3 data-start=\"3806\" data-end=\"3845\" style=\"text-align: justify;\"><strong data-start=\"3810\" data-end=\"3845\">Komitmen Pengembangan Pesantren</strong></h3><p data-start=\"3847\" data-end=\"3958\" style=\"text-align: justify;\">InsyaAllah, Pondok Pesantren Darul Ulum Tlasih berkomitmen untuk terus meningkatkan kualitas dengan fokus pada:</p><ul data-start=\"3960\" data-end=\"4218\">\r\n<li data-start=\"3960\" data-end=\"4000\">\r\n<p data-start=\"3962\" data-end=\"4000\" style=\"text-align: justify;\">Peningkatan kualitas tenaga pendidik</p>\r\n</li>\r\n<li data-start=\"4001\" data-end=\"4057\">\r\n<p data-start=\"4003\" data-end=\"4057\" style=\"text-align: justify;\">Pengembangan fasilitas pendidikan yang representatif</p>\r\n</li>\r\n<li data-start=\"4058\" data-end=\"4093\">\r\n<p data-start=\"4060\" data-end=\"4093\" style=\"text-align: justify;\">Penguatan manajemen kelembagaan</p>\r\n</li>\r\n<li data-start=\"4094\" data-end=\"4152\">\r\n<p data-start=\"4096\" data-end=\"4152\" style=\"text-align: justify;\">Pemanfaatan teknologi digital dalam layanan pendidikan</p>\r\n</li>\r\n<li data-start=\"4153\" data-end=\"4218\">\r\n<p data-start=\"4155\" data-end=\"4218\" style=\"text-align: justify;\">Penciptaan lingkungan belajar yang aman, nyaman, dan kondusif</p>\r\n</li>\r\n</ul><p data-start=\"4220\" data-end=\"4351\" style=\"text-align: justify;\">Kami berharap pesantren ini menjadi rumah bagi generasi Qur’ani yang unggul, berkarakter, dan siap menghadapi tantangan masa depan.</p><hr data-start=\"4353\" data-end=\"4356\" style=\"text-align: justify;\"><h3 data-start=\"4358\" data-end=\"4373\" style=\"text-align: justify;\"><strong data-start=\"4362\" data-end=\"4373\">Penutup</strong></h3><p data-start=\"4375\" data-end=\"4563\" style=\"text-align: justify;\">Semoga kehadiran website resmi dan PSB Online ini memberikan manfaat yang luas, memperkuat kualitas layanan pesantren, serta menjadi bagian dari amal jariyah yang terus mengalir pahalanya.</p><p data-start=\"4565\" data-end=\"4649\" style=\"text-align: justify;\">Kami memohon doa dan dukungan agar seluruh ikhtiar ini selalu dalam ridha Allah SWT.</p><p data-start=\"4651\" data-end=\"4700\" style=\"text-align: justify; \"><strong data-start=\"4651\" data-end=\"4700\">Wassalamu’alaikum warahmatullahi wabarakatuh.</strong></p><hr data-start=\"4702\" data-end=\"4705\" style=\"text-align: justify;\"><p data-start=\"136\" data-end=\"184\" style=\"text-align: justify; \">\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</p><p data-start=\"4707\" data-end=\"4798\"><div style=\"text-align: center;\"><strong data-start=\"4707\" data-end=\"4724\">Ketua Yayasan</strong></div>\r\n<strong data-start=\"4727\" data-end=\"4765\"><div style=\"text-align: center;\"><strong data-start=\"4727\" data-end=\"4765\">Pondok Pesantren Darul Ulum Tlasih</strong></div></strong><div style=\"text-align: center;\"><strong data-start=\"4768\" data-end=\"4798\">Aisatul Mufarrohah, S.Pd.I</strong></div>\r\n</p><p></p>\r\n</div>\r\n</div></div>', '1762426926_e59df1709009023c28f2.png', 'https://maps.app.goo.gl/8dRzcKetcc9ugzjR8', 'https://www.facebook.com/photo.php?fbid=1277160517762138&set=a.343541847790681&type=3&mibextid=rS40aB7S9Ucbxw6v', 'https://www.instagram.com/ppdarululum_tlasih?igsh=MmZidTUwbXIxdDlv', 'https://twitter.com/aplikasipendik1', 'https://youtube.com/@darululumtlasih6763?si=IXNYX1IEfoU1L0km', 1, 'INFORMASI PPDU', '1', '1', '1', '1', '1', 50, 50, 600, 1800, '1', '1', '1', '0', 'smtp.hostinger.com', 'admin@ponpesdarulululum.com', 'Admindu26@', 465, 'PPDU', 'Terima Kasih telah menghubungi kami..!', '', '', '3.0.4', NULL, 1, 3, 'Dibuat dengan <i class=\"mdi mdi-heart text-danger\"></i> V 3.0.4 | Dikelola oleh Darul Ulum Tech ICT & Innovation</a>', NULL, '', '', '', 'Mencetak Generasi yang Beriman, Berilmu, dan Berakhlak Mulia untuk Membawa Perubahan Positif di Dunia dan Akhirat, melalui Pendidikan yang Menggabungkan Ilmu Pengetahuan dan Nilai Agama, serta Membentuk Karakter Pemimpin yang Bertanggung Jawab dan Peduli terhadap Masyarakat.', 'PPDU TLASIH', 'https://waysender-v2.ridped.com');
